**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === now` (exactly expired), the check passes and the token is accepted. It should use `<=`.

**But there's a deeper issue:** `jwt.verify()` already validates expiry and throws `TokenExpiredError` when expired — so the manual check is both redundant and wrong. The fix is to remove it and handle the error types properly instead.

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify() already rejects tokens where exp <= now (inclusive)
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected errors (e.g. missing JWT_SECRET) shouldn't leak internals
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**
- Removed the manual `exp` check — `jwt.verify` uses `exp <= now` (inclusive), which is the correct semantics
- Distinguished `TokenExpiredError` vs `JsonWebTokenError` for clearer client error messages
- Added a 500 fallback for unexpected errors (e.g. `JWT_SECRET` undefined throws `Error`, not a JWT-typed error) so internals don't leak
